from pathlib import Path
import json,sqlite3,re
root=Path('.');out=root/'docs/specifications'
c=sqlite3.connect(':memory:')
for p in sorted((root/'migrations').glob('*.sql')):c.executescript(p.read_text(encoding='utf-8-sig'))
new=set()
for p in sorted((root/'migrations').glob('*.sql')):
 if p.name[:4]>='0018':new.update(re.findall(r'CREATE TABLE(?: IF NOT EXISTS)?\s+(\w+)',p.read_text(encoding='utf-8'),re.I))
new.discard('sales_task_v2')
tables=[]
for name in sorted(new):
 cols=[dict(zip(['cid','name','type','notnull','default','pk'],r)) for r in c.execute('PRAGMA table_info('+name+')')]
 if not cols:continue
 tables.append({'name':name,'columns':cols,'foreign_keys':[list(r)for r in c.execute('PRAGMA foreign_key_list('+name+')')],'indexes':[list(r)for r in c.execute('PRAGMA index_list('+name+')')]})
links=[['customer_outlet','customer_status_snapshot','customer_id'],['customer_segmentation_run','customer_status_snapshot','run_id'],['customer_tier_rule','customer_status_snapshot','rule_id / rule_version snapshot'],['target_plan','target_version','target_plan_id'],['target_version','target_item','target_version_id'],['customer_outlet','target_item','outlet_id (optional customer leaf)'],['app_user','target_item','rep_id_snapshot (optional rep leaf)'],['customer_outlet','work_plan','customer_id'],['app_user','work_session','user_id'],['activity','visit_event','activity_id'],['activity','evidence_attachment','activity_id'],['customer_outlet','sales_task','customer_id'],['customer_outlet','sales_handoff','customer_id'],['sales_campaign','sales_script','campaign_id'],['sales_script','telesales_lease','script_id + immutable lease snapshot'],['telesales_lease','call_result','lease_id'],['customer_outlet','sales_lead','customer_id'],['customer_outlet','sales_order','customer_id'],['sales_order','sales_order_revision','order_id'],['customer_outlet','forecast_contribution','customer_id'],['forecast_contribution','forecast_realization','contribution_id'],['invoice','forecast_realization','source_system / source_invoice_id (logical current revision)']]
j={'version':'M2-local-0.2','date':'2026-10-18','source_of_truth':'migrations/0018-0030 plus preceding schema','tables':tables,'logical_relationships':links,'notes':['Column and FK inventories are physical SQLite results. Logical relationships are not assertions of SQL FK coverage. Tenant/scope/state checks also enforced by prepared application queries and mutation guards.','Money *_minor is whole IDR rupiah. Coordinates E7; accuracy cm. Event and source timestamps distinguished.','No active Account business/legal entity; customer_outlet is one customer at one location.','Original M1 tables target_plan,target_item,activity are extended by M2; see all migrations for complete column inventory.']}
(out/'ERD_M2_Implementation.json').write_text(json.dumps(j,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
md='''# ERD implementasi lokal M2\n\n18 Oktober 2026. Delta terhadap ERD produk v1.2. DDL aktual ada pada migrations 0018–0030, bukan klaim semua entitas rancangan telah dibangun. [Inventaris fisik JSON](ERD_M2_Implementation.json) dibuat dengan mengeksekusi seluruh migrasi pada SQLite kosong, lalu membaca kolom, indeks dan foreign key. Tabel yang sudah ada dan diubah M2: target_plan, target_item, activity.\n\n```mermaid\nerDiagram\n  CUSTOMER_OUTLET ||--o{ CUSTOMER_STATUS_SNAPSHOT : status\n  CUSTOMER_SEGMENTATION_RUN ||--o{ CUSTOMER_STATUS_SNAPSHOT : freezes\n  CUSTOMER_TIER_RULE ||--o{ CUSTOMER_STATUS_SNAPSHOT : version\n  TARGET_PLAN ||--o{ TARGET_VERSION : revisions\n  TARGET_VERSION ||--o{ TARGET_ITEM : leaf\n  CUSTOMER_OUTLET ||--o{ WORK_PLAN : agenda\n  APP_USER ||--o{ WORK_SESSION : attendance\n  ACTIVITY ||--o{ VISIT_EVENT : immutable\n  ACTIVITY ||--o{ EVIDENCE_ATTACHMENT : private\n  CUSTOMER_OUTLET ||--o{ SALES_TASK : next_action\n  CUSTOMER_OUTLET ||--o{ SALES_HANDOFF : cross_channel\n  SALES_CAMPAIGN ||--o{ SALES_SCRIPT : guidance\n  SALES_SCRIPT ||--o{ TELESALES_LEASE : snapshot\n  TELESALES_LEASE ||--o| CALL_RESULT : disposition\n  CUSTOMER_OUTLET ||--o{ SALES_LEAD : opportunity\n  CUSTOMER_OUTLET ||--o{ SALES_ORDER : draft\n  SALES_ORDER ||--o{ SALES_ORDER_REVISION : immutable\n  CUSTOMER_OUTLET ||--o{ FORECAST_CONTRIBUTION : basket\n  FORECAST_CONTRIBUTION ||--o{ FORECAST_REALIZATION : attribution\n  INVOICE ||--o{ FORECAST_REALIZATION : logical_identity\n```\n\nGraf menunjukkan relasi logis, bukan jaminan seluruh garis mempunyai constraint FK fisik. Setiap query memakai organization_id serta scope. Relasi invoice mengikuti identitas sumber dan revisi current, sehingga revisi/retur tidak menggandakan actual. Tabel snapshot dan event mempunyai trigger immutable.\n\nTarget menyimpan leaf pelanggan ATAU sales rep, basis revenue/produk/group, snapshot area/rep/kanal/hirarki. Parent dan reserve bukan tambahan leaf actual. Satu plan approved per kanal pada periode beririsan merupakan batas pilot.\n\nForecast sales dan alternatif manager adalah dua pandangan terpisah. Satu basket aktif per customer/kanal/view/bulan. Omitted membebaskan basket; merge/revisi invoice yang ambigu menahan angka untuk review. Confirmed order belum menjadi invoice.\n\nScript pada lease dan hasil panggilan dibekukan dengan versinya. Mutasi script berikutnya tidak mengubah qualification pada lease aktif. Evidence hanya metadata di D1; byte disimpan di R2 privat, melalui API autentikasi.\n\nTidak ada relasi Account bisnis/legal. Alias pelanggan dan seluruh fakta keuangan lama dipertahankan. Android/GPS background dan tabel finalisasi insentif tidak termasuk slice M2 ini.\n'''
(out/'ERD_M2_Implementation.md').write_text(md,encoding='utf-8')
print('M2 physical tables',len(tables))
